function noise(d=.1,vol=.06,freq=1200,when=0){if(muted||!audio)return;try{if(!noiseBuf){noiseBuf=audio.createBuffer(1,audio.sampleRate*.5,audio.sampleRate);const c=noiseBuf.getChannelData(0);for(let i=0;i<c.length;i++)c[i]=Math.random()*2-1}const t=when||audio.currentTime,s=audio.createBufferSource(),f=audio.createBiquadFilter(),g=audio.createGain();s.buffer=noiseBuf;f.type='lowpass';f.frequency.value=freq;g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(f);f.connect(g);g.connect(audio.destination);s.start(t);s.stop(t+d)}catch{}}
