function image(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('No se pudo cargar '+src));im.src=src})}
function keyedCanvas(im){const a=document.createElement('canvas');a.width=im.width;a.height=im.height;const c=a.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0);const d=c.getImageData(0,0,a.width,a.height);for(let i=0;i<d.data.length;i+=4){const r=d.data[i],g=d.data[i+1],b=d.data[i+2];if(r>155&&b>155&&g<110&&Math.min(r,b)-g>100)d.data[i+3]=0}c.putImageData(d,0,0);return a}
function components(a){const c=a.getContext('2d',{willReadFrequently:true}),pixels=c.getImageData(0,0,a.width,a.height),d=pixels.data,w=a.width,h=a.height,labels=new Int32Array(w*h),queue=new Int32Array(w*h),groups=[];let id=0;
 for(let seed=0;seed<labels.length;seed++){if(labels[seed]||!d[seed*4+3])continue;id++;let head=0,tail=1,minX=w,minY=h,maxX=0,maxY=0;labels[seed]=id;queue[0]=seed;while(head<tail){const at=queue[head++],x=at%w,y=Math.floor(at/w);minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const nx=x+dx,ny=y+dy;if(nx<0||nx>=w||ny<0||ny>=h)continue;const n=ny*w+nx;if(!labels[n]&&d[n*4+3]){labels[n]=id;queue[tail++]=n}}}groups.push({id,size:tail,x:minX,y:minY,w:maxX-minX+1,h:maxY-minY+1})}return{pixels,labels,groups};}
function isolateSprite(a){const {pixels,labels,groups}=components(a),largest=groups.sort((a,b)=>b.size-a.size)[0];for(let i=0;i<labels.length;i++)if(labels[i]!==largest?.id)pixels.data[i*4+3]=0;a.getContext('2d').putImageData(pixels,0,0);return a;}
function crop(a,x,y,w,h){const out=document.createElement('canvas');out.width=w;out.height=h;out.getContext('2d').drawImage(a,x,y,w,h,0,0,w,h);return isolateSprite(out)}
function extractPoses(im,columns=6){const a=keyedCanvas(im),{groups}=components(a);const bodies=groups.filter(g=>g.size>3000).sort((a,b)=>b.size-a.size).slice(0,columns*2);if(bodies.length!==columns*2)throw Error('El atlas de movimientos tiene siluetas incompletas');const top=bodies.filter(g=>g.y+g.h/2<im.height/2).sort((a,b)=>a.x-b.x),bottom=bodies.filter(g=>g.y+g.h/2>=im.height/2).sort((a,b)=>a.x-b.x);if(top.length!==columns||bottom.length!==columns)throw Error('Distribución de poses inesperada');return [...top,...bottom].map(g=>({image:crop(a,g.x,g.y,g.w,g.h),height:g.h}));}
function extractRow(im,count){const a=keyedCanvas(im),{groups}=components(a),bodies=groups.filter(g=>g.size>1500).sort((x,y)=>y.size-x.size).slice(0,count).sort((x,y)=>x.x-y.x);if(bodies.length!==count)throw Error('El atlas de voltereta tiene siluetas incompletas');return bodies.map(g=>({image:crop(a,g.x,g.y,g.w,g.h),height:g.h}))}
