const CROWD_SCALE=1.35;   // overall size of the spectators
const crowdCache={};
function crowdStageId(){try{return GAME_ASSETS.stages[front.stage].id}catch{return'patio-fisi'}}
function crowdRows(id){return crowdCache[id]??=(()=>{const cfg=CROWD_STAGES[id]||CROWD_STAGES['patio-fisi'];return cfg.rows.map((r,ri)=>({key:ri?'front':'back',k:r.k,base:r.base,sway:ri?1:.8,list:Array.from({length:Math.ceil((WORLD+60)/r.step)},(_,i)=>({i,x:(ri?28:6)+i*r.step+((i*37)%11),s:(i*7+(ri?2:5)+((i*i)%3))%21,flip:(i*5+(ri?0:1))%2===0,phase:i*1.7+(ri?0:.9)})).filter(c=>((c.i*53+ri*17)%100)/100>=cfg.gap&&!cfg.skip.some(([a,b])=>c.x>=a&&c.x<=b))}))})()}
function buildSpectators(atlas){const names=Object.keys(SPECT_ATLAS);for(const row of ['front','back']){spect[row]=names.map(n=>{const m=SPECT_ATLAS[n],c=document.createElement('canvas');c.width=m[2];c.height=m[3];const g=c.getContext('2d');g.drawImage(atlas,m[0],m[1],m[2],m[3],0,0,m[2],m[3]);g.globalCompositeOperation='source-atop';g.fillStyle=row==='back'?'rgba(24,14,50,.42)':'rgba(38,22,72,.2)';g.fillRect(0,0,c.width,c.height);return{canvas:c,w:m[2]/2,h:m[3]/2,anchor:m[4]}})}}
function drawCrowd(){if(!spect.front.length)return;for(const row of crowdRows(crowdStageId())){const sprites=spect[row.key];for(const c of row.list){const sp=sprites[c.s%sprites.length],jump=Math.abs(Math.sin(fxClock*(9+c.phase%3)+c.phase))*hype*13*row.sway,bob=Math.sin(fxClock*2+c.phase)*1.2,tilt=Math.sin(fxClock*3+c.phase)*.025*Math.min(1,hype+.2),w=sp.w*row.k*CROWD_SCALE,h=sp.h*row.k*CROWD_SCALE;ctx.save();ctx.translate(c.x,row.base-jump+bob);ctx.rotate(tilt);if(c.flip)ctx.scale(-1,1);ctx.drawImage(sp.canvas,-w*(c.flip?1-sp.anchor:sp.anchor),-h,w,h);ctx.restore()}}}
function drawSpotlights(color,strength,center){if(reducedFX||strength<=0)return;ctx.save();ctx.globalCompositeOperation='lighter';for(let i=0;i<3;i++){const sx=center-300+i*300,swing=Math.sin(fxClock*1.3+i*2)*160,g=ctx.createLinearGradient(sx,-120,sx+swing,FLOOR);g.addColorStop(0,color+'55');g.addColorStop(1,color+'00');ctx.globalAlpha=strength*.5;ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(sx-12,-120);ctx.lineTo(sx+12,-120);ctx.lineTo(sx+swing+90,FLOOR);ctx.lineTo(sx+swing-90,FLOOR);ctx.closePath();ctx.fill()}ctx.restore()}
