 ctx.globalAlpha=.25;for(let i=0;i<26;i++){const y=(i*41)%H,x=((t*900+i*137)%(W+300))-150;rect(i%2?x:W-x,y,120+i%4*40,2,i%2?THEMES[a.id].color:THEMES[b.id].color)}ctx.restore();
