 for(const p of players)if(p.action==='charge'&&p.age>.2){const t=THEMES[p.id],r=60+Math.sin(p.age*10)*8,g=ctx.createRadialGradient(p.x,FLOOR-95,10,p.x,FLOOR-95,r+60);g.addColorStop(0,t.color+'88');g.addColorStop(1,t.color+'00');ctx.fillStyle=g;ctx.fillRect(p.x-140,FLOOR-260,280,300)}
