function drawBall(s){const dir=Math.sign(s.vx),r=s.super?20:s.low?15:17;ctx.save();ctx.shadowColor='#ff9a3c';ctx.shadowBlur=s.super?26:14;ctx.globalAlpha=.4;for(let i=1;i<=3;i++)rect(s.x-dir*(r+i*18),s.y-3+i*2-3,26-i*4,3,'#ffb15e');ctx.globalAlpha=1;ctx.translate(s.x,s.y);ctx.rotate(tick*9*dir);ctx.fillStyle=s.super?'#ffb15e':'#f08a24';ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#4a2308';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.moveTo(-r,0);ctx.lineTo(r,0);ctx.moveTo(0,-r);ctx.lineTo(0,r);ctx.stroke();ctx.beginPath();ctx.arc(-r*1.05,0,r*.72,-1.2,1.2);ctx.arc(r*1.05,0,r*.72,Math.PI-1.2,Math.PI+1.2);ctx.stroke();ctx.restore()}
